<?php
require __DIR__.'/concurrency.php';
function m5_config($unit='hours',$factor=1){$c=array();for($s=1;$s<=4;$s++){$c['nudge_'.$s]=array('enabled'=>true,'value'=>$s*$factor,'unit'=>$unit);}return $c;}
function m5_assignment(){global $wpdb;return $wpdb->get_row("SELECT a.*,w.nudge_config,w.follow_up_reminders_enabled FROM {$wpdb->prefix}survey_assignments a JOIN {$wpdb->prefix}survey_waves w ON w.id=a.wave_id WHERE a.id=992231");}
function m5_set($changes){global $wpdb;m0_assert($wpdb->update($wpdb->prefix.'survey_assignments',$changes,array('id'=>992231))!==false,$wpdb->last_error);}
function m5_wave_config($c){global $wpdb;$wpdb->update($wpdb->prefix.'survey_waves',array('nudge_config'=>wp_json_encode($c),'follow_up_reminders_enabled'=>1),array('id'=>992221));}
function m5_plan($assignment=null,$config=null,$now=null){return EIPSI_Notification_Nudge_Policy_Service::follow_up_plan($assignment?:m5_assignment(),$config?:json_decode(m5_assignment()->nudge_config,true),null,$now);}
function m5_events(){return array_values(array_filter(EIPSI_Nudge_Event_Scheduler::get_scheduled_events(),function($e){return (int)$e['assignment_id']===992231;}));}
function m5_job($type='send_nudge_1',$assignment=992231,$priority=10,$when=null){$id=EIPSI_Nudge_Job_Queue::enqueue($type,array('assignment_id'=>$assignment,'participant_id'=>992207,'study_id'=>992203,'wave_id'=>992221),$priority,$when);m0_assert($id,'Queue insert failed');$GLOBALS['m5_jobs'][]=$id;return $id;}
function m5_job_row($id){global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}survey_nudge_jobs WHERE id=%d",$id));}
function m5_mail_fail($pre,$atts){do_action('wp_mail_failed',new WP_Error('controlled_failure','M5 controlled delivery failure'));return false;}
function m5_notification_reset(){
 global $wpdb;$GLOBALS['m0_mail']=array();remove_filter('pre_wp_mail','m5_mail_fail',PHP_INT_MAX);
 foreach(($GLOBALS['m5_jobs']??array()) as $id){$wpdb->delete($wpdb->prefix.'survey_nudge_jobs',array('id'=>$id));}$GLOBALS['m5_jobs']=array();
 $wpdb->delete($wpdb->prefix.'survey_email_log',array('survey_id'=>992203));
 $wpdb->delete($wpdb->prefix.'survey_weekly_reminders',array('assignment_id'=>992231));
 $wpdb->update($wpdb->prefix.'survey_participants',array('created_at'=>current_time('mysql')),array('id'=>992207));
 foreach(array(992231,992232,992233) as $id){EIPSI_Nudge_Cache::invalidate_assignment_cache($id);}
 foreach(array(992221,992222,992223) as $wave){
  foreach(array('eipsi_wave_email_retries_','eipsi_nudge_0_sent_','eipsi_recovery_') as $prefix){$key=$prefix.'992207_'.$wave;delete_transient($key);delete_option($key);$GLOBALS['m5_options'][]=$key;}
 }
 $wpdb->update($wpdb->prefix.'survey_assignments',array('status'=>'submitted','reminder_count'=>0),array('study_id'=>992203));
 m5_set(array('status'=>'pending','reminder_count'=>1,'available_at'=>date('Y-m-d H:i:s',current_time('timestamp')-600),'due_at'=>date('Y-m-d H:i:s',current_time('timestamp')+21600),'last_nudge_sent_at'=>null));
 m5_wave_config(m5_config());
 foreach(m5_events() as $e){wp_clear_scheduled_hook('eipsi_scheduled_nudge_event',array(array('assignment_id'=>$e['assignment_id'],'stage'=>$e['stage'])));}
}
function m5_assert_plan_events(){
 $events=m5_events();$plan=m5_plan();m0_assert(count($events)===count($plan),'Event count differs from plan');
 foreach($events as $event){m0_assert(isset($plan[$event['stage']])&&$plan[$event['stage']]['timestamp']===$event['timestamp'],'Event differs from absolute plan');}
}
function m5_weekly_enable($extra=array()){global $wpdb;$wpdb->update($wpdb->prefix.'survey_studies',array('config'=>wp_json_encode(array('weekly_reminders'=>array_merge(array('enabled'=>true,'start_after_nudge'=>1,'frequency_days'=>7),$extra)))),array('id'=>992203));}
$contracts=json_decode(file_get_contents(__DIR__.'/contracts.json'),true);
foreach($contracts['templates'] as $file=>$hash){$tests['Frozen template '.$file]=function()use($file,$hash){m0_assert(hash_file('sha256',EIPSI_FORMS_PLUGIN_DIR.$file)===$hash,'Email template changed');};}
foreach($contracts['public_signatures'] as $file=>$signatures){$tests['Frozen public facade '.$file]=function()use($file,$signatures){$source=file_get_contents(EIPSI_FORMS_PLUGIN_DIR.$file);foreach($signatures as $signature){m0_assert(strpos($source,$signature)!==false,'Public signature changed: '.$signature);}};}
$tests['Absolute stages 1 to 4']=function(){$a=m5_assignment();$p=m5_plan();foreach(range(1,4) as $s){m0_assert($p[$s]['timestamp']===strtotime($a->available_at)+$s*3600,'Cumulative timing');}};
$tests['Fractional minute offset preserved']=function(){$a=m5_assignment();$a->available_at=date('Y-m-d H:i:s',time()+60);$p=m5_plan($a,m5_config('minutes',1.2));m0_assert($p[1]['timestamp']===strtotime($a->available_at)+72,'Minute precision');};
foreach(array('minutes'=>60,'hours'=>3600,'days'=>86400,'minutos'=>60,'horas'=>3600,'dias'=>86400) as $unit=>$seconds){$tests['Schedule conversion '.$unit]=function()use($unit,$seconds){m0_assert(EIPSI_Notification_Nudge_Policy_Service::schedule_seconds(2,$unit)===2*$seconds,'Conversion changed');};}
$tests['No stages in past']=function(){m5_set(array('available_at'=>date('Y-m-d H:i:s',time()-5*3600)));m0_assert(m5_plan()===array(),'Past stages scheduled');};
$tests['No stages at or after deadline']=function(){$a=m5_assignment();$a->due_at=date('Y-m-d H:i:s',strtotime($a->available_at)+3600);m0_assert(m5_plan($a)===array(),'At-deadline stage accepted');};
$tests['Sent stages excluded']=function(){m5_set(array('reminder_count'=>3));m0_assert(array_keys(m5_plan())===array(3,4),'Sent stages repeated');};
$tests['Disabled stage absent']=function(){$c=m5_config();$c['nudge_2']['enabled']=false;m0_assert(array_keys(m5_plan(null,$c))===array(1,3,4),'Disabled stage scheduled');};
$tests['Real WP cron matches policy plan']=function(){EIPSI_Nudge_Event_Scheduler::schedule_nudge_sequence(992231);m5_assert_plan_events();};
$tests['Repeated availability does not resend nudge zero']=function(){EIPSI_Nudge_Event_Scheduler::schedule_nudge_sequence(992231);EIPSI_Nudge_Event_Scheduler::schedule_nudge_sequence(992231);m5_assert_plan_events();m0_assert(count($GLOBALS['m0_mail'])===0,'Nudge0 resent');};
$tests['Config refresh uses fresh absolute offsets']=function(){EIPSI_Nudge_Event_Scheduler::schedule_nudge_sequence(992231);m5_wave_config(m5_config('hours',1.25));EIPSI_Nudge_Event_Scheduler::refresh_wave_follow_ups(992221,992231);m5_assert_plan_events();};
$tests['Deadline change rebuilds bounded plan']=function(){EIPSI_Nudge_Event_Scheduler::schedule_nudge_sequence(992231);m5_set(array('due_at'=>date('Y-m-d H:i:s',time()+5400)));do_action('eipsi_assignment_deadline_changed',992231);m5_assert_plan_events();m0_assert(count(m5_events())===1,'Deadline not consumed');};
$tests['Cancellation removes real cron stages']=function(){EIPSI_Nudge_Event_Scheduler::schedule_nudge_sequence(992231);EIPSI_Nudge_Event_Scheduler::cancel_scheduled_nudges(992231);m0_assert(m5_events()===array(),'Cancellation incomplete');};
$tests['Disable followups preserves configuration and cancels jobs']=function(){global $wpdb;$job=m5_job();EIPSI_Nudge_Event_Scheduler::schedule_nudge_sequence(992231);$wpdb->update($wpdb->prefix.'survey_waves',array('follow_up_reminders_enabled'=>0),array('id'=>992221));EIPSI_Nudge_Event_Scheduler::refresh_wave_follow_ups(992221,992231);m0_assert(m5_events()===array()&&m5_job_row($job)->status==='cancelled'&&m5_assignment()->nudge_config!=='{}','Disabled config lost');};
$tests['Catchup successor uses absolute plan']=function(){EIPSI_Notification_Nudge_Schedule_Service::reschedule_next_stage(992231,1);$e=m5_events();m0_assert(count($e)===1&&$e[0]['timestamp']===strtotime(m5_assignment()->available_at)+7200,'Catchup shifted from now');};
$tests['Catchup successor excluded beyond due']=function(){m5_set(array('due_at'=>date('Y-m-d H:i:s',time()+1200)));EIPSI_Notification_Nudge_Schedule_Service::reschedule_next_stage(992231,1);m0_assert(m5_events()===array(),'Catchup beyond due');};
$tests['T1 anchored legacy pending cancellation characterized']=function(){global $wpdb;$wpdb->update($wpdb->prefix.'survey_assignments',array('status'=>'pending','reminder_count'=>1,'available_at'=>date('Y-m-d H:i:s',time()-600),'due_at'=>date('Y-m-d H:i:s',time()+21600)),array('id'=>992232));$a=$wpdb->get_row("SELECT * FROM {$wpdb->prefix}survey_assignments WHERE id=992232");$a->follow_up_reminders_enabled=1;$wpdb->update($wpdb->prefix.'survey_waves',array('nudge_config'=>wp_json_encode(m5_config()),'follow_up_reminders_enabled'=>1),array('id'=>992222));EIPSI_Nudge_Event_Scheduler::schedule_follow_up_nudges_only($a);EIPSI_Nudge_Event_Scheduler::reschedule_all_nudges_for_participant(992203,992207);foreach(EIPSI_Nudge_Event_Scheduler::get_scheduled_events() as $e){m0_assert((int)$e['assignment_id']!==992232,'Existing T1 cancellation contract changed');}};
$tests['Scheduler failure leaves committed config']=function(){
 require_once EIPSI_FORMS_PLUGIN_DIR.'includes/services/class-nudge-service.php';
 $c=m5_config('minutes',60);$committed=false;$attempted=false;
 $query=function($sql)use(&$committed){if(strtoupper(trim($sql))==='COMMIT'){$committed=true;}return $sql;};
 $fail=function($pre,$event)use(&$committed,&$attempted){if($event->hook!=='eipsi_scheduled_nudge_event'){return $pre;}$attempted=$committed;return false;};
 add_filter('query',$query);add_filter('pre_schedule_event',$fail,10,2);
 try{$result=EIPSI_Nudge_Service::save_wave_configuration(992221,$c);m0_assert($attempted&&is_wp_error($result)&&json_decode(m5_assignment()->nudge_config,true)===$c,'Config was rolled back or scheduling did not follow COMMIT');}
 finally{remove_filter('query',$query);remove_filter('pre_schedule_event',$fail,10);}
};
$tests['Cache sent marking and invalidation']=function(){EIPSI_Nudge_Cache::mark_nudge_sent(992231,1);m0_assert(EIPSI_Nudge_Cache::is_nudge_sent(992231,1)===true,'Sent marker absent');EIPSI_Nudge_Cache::invalidate_assignment_cache(992231);m0_assert(EIPSI_Nudge_Cache::get_cached_should_send(992231,1)===null,'Cache invalidation failed');};
$tests['Nudge0 sends and advances count once']=function(){m5_set(array('reminder_count'=>0));$r=EIPSI_Nudge_Job_Queue::execute_nudge_0(array('assignment_id'=>992231));m0_assert($r['success']&&(int)m5_assignment()->reminder_count===1&&count($GLOBALS['m0_mail'])===1,'Nudge0 failed');$r=EIPSI_Nudge_Job_Queue::execute_nudge_0(array('assignment_id'=>992231));m0_assert($r['success']&&count($GLOBALS['m0_mail'])===1,'Nudge0 repeated');};
$tests['Nudge0 cannot notify future availability']=function(){m5_set(array('reminder_count'=>0,'available_at'=>date('Y-m-d H:i:s',time()+3600)));$r=EIPSI_Nudge_Job_Queue::execute_nudge_0(array('assignment_id'=>992231));m0_assert(!$r['success']&&count($GLOBALS['m0_mail'])===0,'Future nudge0 sent');};
$tests['Nudge0 failure stores retry diagnostics']=function(){m5_set(array('reminder_count'=>0));add_filter('pre_wp_mail','m5_mail_fail',PHP_INT_MAX,2);$r=EIPSI_Nudge_Job_Queue::execute_nudge_0(array('assignment_id'=>992231));$retry=get_transient('eipsi_wave_email_retries_992207_992221');m0_assert(!$r['success']&&(int)m5_assignment()->reminder_count===0&&$retry['attempts']===1&&!empty($retry['errors']),'Failure lost');};
$tests['Nudge0 retry cooldown prevents another send']=function(){m5_set(array('reminder_count'=>0));set_transient('eipsi_wave_email_retries_992207_992221',array('attempts'=>1,'last_attempt'=>time(),'errors'=>array()),3600);$r=EIPSI_Nudge_Job_Queue::execute_nudge_0(array('assignment_id'=>992231));m0_assert(!$r['success']&&$r['error']==='retry_cooldown'&&count($GLOBALS['m0_mail'])===0,'Cooldown bypass');};
$tests['Nudge0 retry maximum preserved']=function(){m5_set(array('reminder_count'=>0));set_transient('eipsi_wave_email_retries_992207_992221',array('attempts'=>3,'last_attempt'=>0,'errors'=>array()),3600);$r=EIPSI_Nudge_Job_Queue::execute_nudge_0(array('assignment_id'=>992231));m0_assert(!$r['success']&&count($GLOBALS['m0_mail'])===0,'Retry max bypass');};
$tests['Stages 1 and 2 update count and sent marker']=function(){foreach(array(1,2) as $stage){$r=EIPSI_Nudge_Job_Queue::execute_nudge_followup(array('assignment_id'=>992231),$stage);m0_assert($r['success']&&(int)m5_assignment()->reminder_count===$stage+1&&EIPSI_Nudge_Cache::is_nudge_sent(992231,$stage),'Followup state failed');}m0_assert(count($GLOBALS['m0_mail'])===2,'Delivery count differs');};
$tests['Repeated scheduled stage guarded by persisted count']=function(){EIPSI_Nudge_Event_Scheduler::execute_scheduled_nudge(array('assignment_id'=>992231,'stage'=>1));EIPSI_Nudge_Event_Scheduler::execute_scheduled_nudge(array('assignment_id'=>992231,'stage'=>1));m0_assert((int)m5_assignment()->reminder_count===2&&count($GLOBALS['m0_mail'])===1,'Repeated event resent');};
$tests['Queue creates distinct jobs without exactly-once assumption']=function(){$a=m5_job();$b=m5_job();m0_assert($a!==$b&&m5_job_row($a)->status==='pending'&&m5_job_row($b)->status==='pending','Distinct enqueue conflated');};
$tests['Atomic claim only first wins']=function(){$id=m5_job();m0_assert(EIPSI_Nudge_Job_Queue::mark_processing($id)&&!EIPSI_Nudge_Job_Queue::mark_processing($id)&&m5_job_row($id)->status==='processing','Claim duplicated');};
$tests['Worker completes owned job and records result']=function(){$id=m5_job();$r=EIPSI_Notification_Nudge_Worker_Service::process_job(m5_job_row($id));m0_assert($r['completed']===1&&m5_job_row($id)->status==='completed'&&!empty(m5_job_row($id)->result),'Job not completed');};
$tests['Worker delivery failure requeues with backoff']=function(){$id=m5_job();add_filter('pre_wp_mail','m5_mail_fail',PHP_INT_MAX,2);$r=EIPSI_Notification_Nudge_Worker_Service::process_job(m5_job_row($id));$j=m5_job_row($id);m0_assert($r['retried']===1&&$j->status==='pending'&&(int)$j->retries===1&&strtotime($j->scheduled_at)>=time()+295&&(int)m5_assignment()->reminder_count===1,'Retry state incorrect');};
$tests['Irrecoverable failure is permanent']=function(){$id=m5_job('send_nudge_1',99999999);$r=EIPSI_Notification_Nudge_Worker_Service::process_job(m5_job_row($id));m0_assert($r['failed']===1&&m5_job_row($id)->status==='failed'&&strpos(m5_job_row($id)->error,'IRRECOVERABLE')!==false,'Permanent failure retried');};
$tests['Retry exhaustion at five attempts']=function(){$id=m5_job();for($i=1;$i<=5;$i++){global $wpdb;$wpdb->update($wpdb->prefix.'survey_nudge_jobs',array('scheduled_at'=>current_time('mysql')),array('id'=>$id));m0_assert(EIPSI_Nudge_Job_Queue::mark_processing($id),'Retry requires owned processing claim');$r=EIPSI_Nudge_Job_Queue::mark_for_retry($id,'Email sending failed');m0_assert($r===($i<5),'Retry boundary');}m0_assert(m5_job_row($id)->status==='failed'&&(int)m5_job_row($id)->retries===5,'Exhaustion state');};
$tests['Pending selection excludes future jobs and preserves priority']=function(){$slow=m5_job('send_nudge_1',992231,90);$fast=m5_job('send_nudge_1',992231,1);$future=m5_job('send_nudge_1',992231,1,date('Y-m-d H:i:s',time()+3600));$ids=array_map(function($j){return (int)$j->id;},EIPSI_Nudge_Job_Queue::get_pending_jobs(10000));m0_assert(in_array($fast,$ids,true)&&in_array($slow,$ids,true)&&!in_array($future,$ids,true)&&array_search($fast,$ids)<array_search($slow,$ids),'Queue selection changed');};
$tests['Two workers same real job one claim and delivery']=function(){$id=m5_job();$r=m5_concurrent('worker',array($id,$id));m0_assert($r[0]['completed']+$r[1]['completed']===1&&m5_job_row($id)->status==='completed'&&(int)m5_assignment()->reminder_count===2,'Concurrent workers incoherent: '.wp_json_encode(array($r,m5_job_row($id),m5_assignment())));global $wpdb;m0_assert((int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}survey_email_log WHERE survey_id=992203 AND status='sent'")===1,'Same job delivered twice');};
$tests['Two connections atomic pending claim']=function(){$id=m5_job();$r=m5_concurrent('claim',array($id,$id));sort($r);m0_assert($r===array(false,true)&&m5_job_row($id)->status==='processing','Cross-process claim not atomic: '.wp_json_encode(array($r,m5_job_row($id))));};
$tests['Two schedulers same assignment produce one event per stage']=function(){m5_concurrent('schedule');m5_assert_plan_events();};
$tests['Concurrent config refresh final cron follows fresh database']=function(){m5_concurrent('reschedule',array(),array(m5_config('hours',1),m5_config('hours',1.25)));m5_assert_plan_events();};
$tests['Distinct jobs same assignment stages converge after retry']=function(){global $wpdb;$a=m5_job('send_nudge_1');$b=m5_job('send_nudge_2');m5_concurrent('worker',array($a,$b));if(m5_job_row($b)->status==='pending'){$wpdb->update($wpdb->prefix.'survey_nudge_jobs',array('scheduled_at'=>current_time('mysql')),array('id'=>$b));EIPSI_Notification_Nudge_Worker_Service::process_job(m5_job_row($b));}m0_assert(m5_job_row($a)->status==='completed'&&m5_job_row($b)->status==='completed'&&(int)m5_assignment()->reminder_count===3,'Distinct jobs did not converge');};
$tests['Delivery returns sent log id with headers subject metadata']=function(){global $wpdb;$id=EIPSI_Email_Service::send_email(992203,992207,'m2-a@example.invalid','m5_probe','M5 subject','<p>M5 body</p>',array('stage'=>2));$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}survey_email_log WHERE id=%d",$id));$mail=end($GLOBALS['m0_mail']);m0_assert($id>0&&$row->status==='sent'&&$mail['subject']==='M5 subject'&&strpos(implode(' ',(array)$mail['headers']),'text/html')!==false&&json_decode($row->metadata,true)['stage']===2,'Delivery contract altered');};
$tests['Delivery failure returns false and failed log']=function(){global $wpdb;add_filter('pre_wp_mail','m5_mail_fail',PHP_INT_MAX,2);$r=EIPSI_Email_Service::send_email(992203,992207,'m2-a@example.invalid','m5_probe','M5 subject','body',array('stage'=>2));$row=$wpdb->get_row("SELECT * FROM {$wpdb->prefix}survey_email_log WHERE survey_id=992203 ORDER BY id DESC LIMIT 1");m0_assert($r===false&&$row->status==='failed'&&strpos($row->error_message,'controlled')!==false,'Failure contract lost');};
