$tests['Weekly T1 failure does not record sent weekly row']=function(){global $wpdb;m5_weekly_enable();add_filter('pre_wp_mail','m5_mail_fail',PHP_INT_MAX,2);eipsi_weekly_t1_reminders();m0_assert((int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}survey_weekly_reminders WHERE assignment_id=992231")===0,'Failed weekly logged sent');};
$tests['Dropout sends with persisted rate limit']=function(){global $wpdb;$wpdb->update($wpdb->prefix.'survey_studies',array('config'=>'{"dropout_recovery_enabled":true,"dropout_recovery_days":7}'),array('id'=>992203));$wpdb->update($wpdb->prefix.'survey_participants',array('created_at'=>date('Y-m-d H:i:s',time()-40*86400)),array('id'=>992207));eipsi_send_dropout_recovery_hourly();m0_assert((int)m5_assignment()->reminder_count===2&&count($GLOBALS['m0_mail'])===1,'Recovery failed');eipsi_send_dropout_recovery_hourly();m0_assert(count($GLOBALS['m0_mail'])===1,'Recovery rate limit bypass');};
