$tests['Manual wave reminder through existing batch API']=function(){$r=EIPSI_Email_Service::send_manual_reminders(992203,array(992207),992221,'M5 custom');m0_assert($r['sent_count']===1&&strpos(end($GLOBALS['m0_mail'])['subject'],'Toma 1')!==false,'Manual wave flow failed');};
