$tests['Cron observers retain priority 999']=function(){global $wp_filter;foreach(array('eipsi_send_wave_reminders_hourly','eipsi_send_dropout_recovery_hourly') as $hook){m0_assert(isset($wp_filter[$hook]->callbacks[999]),'Health observer absent');}};
$tests['Legacy and current wave callbacks remain registered']=function(){m0_assert(has_action('eipsi_send_wave_reminders_hourly','eipsi_run_send_wave_reminders')!==false&&has_action('eipsi_send_wave_reminders_hourly','eipsi_send_wave_reminders_hourly')!==false,'Legacy/current callback removed');};
$tests['Deprecated daily weekly callbacks remain log only']=function(){$before=count($GLOBALS['m0_mail']);eipsi_send_take_reminders_daily();eipsi_send_take_reminders_weekly();m0_assert(count($GLOBALS['m0_mail'])===$before,'Deprecated log callback started sending');};
$tests['Scheduled delivery transaction ordering preserved']=function(){$trace=array();$observe=function($q)use(&$trace){if(in_array(strtoupper(trim($q)),array('START TRANSACTION','COMMIT','ROLLBACK'),true)){$trace[]=strtoupper(trim($q));}return $q;};$mail=function($pre)use(&$trace){$trace[]='MAIL';return $pre;};add_filter('query',$observe);add_filter('pre_wp_mail',$mail,PHP_INT_MAX);try{EIPSI_Nudge_Event_Scheduler::execute_scheduled_nudge(array('assignment_id'=>992231,'stage'=>1));m0_assert(array_search('START TRANSACTION',$trace)<array_search('MAIL',$trace)&&array_search('MAIL',$trace)<array_search('COMMIT',$trace),'Delivery transaction moved');}finally{remove_filter('query',$observe);remove_filter('pre_wp_mail',$mail,PHP_INT_MAX);}};
$tests['Legacy wave post meta pipeline still delivers']=function(){
 global $wpdb;$wpdb->update($wpdb->prefix.'survey_waves',array('due_date'=>date('Y-m-d H:i:s',time()+86400)),array('id'=>992221));
 $posts=function($pre,$query){return $query->get('post_type')==='eipsi_form'?array(992203):$pre;};
 $meta=function($pre,$id,$key){if((int)$id!==992203){return $pre;}if($key==='_eipsi_reminders_enabled'){return 1;}if($key==='_eipsi_reminder_days_before'){return 3;}return $pre;};
 add_filter('posts_pre_query',$posts,10,2);add_filter('get_post_metadata',$meta,10,3);
 try{eipsi_run_send_wave_reminders();m0_assert(count($GLOBALS['m0_mail'])===1,'Legacy wave no delivery');eipsi_run_send_wave_reminders();m0_assert(count($GLOBALS['m0_mail'])===1,'Legacy rate limit broken');}
 finally{remove_filter('posts_pre_query',$posts,10);remove_filter('get_post_metadata',$meta,10);delete_transient('eipsi_reminder_sent_992207_992221');}
};
$tests['Legacy deferred manual cron still delivers']=function(){do_action('eipsi_send_manual_reminder','m5@example.invalid','https://example.invalid/survey');m0_assert(count($GLOBALS['m0_mail'])===1,'Deferred reminder lost');};
$tests['Dropout failed delivery keeps count and does not rate limit']=function(){global $wpdb;$wpdb->update($wpdb->prefix.'survey_studies',array('config'=>'{"dropout_recovery_enabled":true,"dropout_recovery_days":7}'),array('id'=>992203));$wpdb->update($wpdb->prefix.'survey_participants',array('created_at'=>date('Y-m-d H:i:s',time()-40*86400)),array('id'=>992207));add_filter('pre_wp_mail','m5_mail_fail',PHP_INT_MAX,2);eipsi_send_dropout_recovery_hourly();m0_assert((int)m5_assignment()->reminder_count===1&&!get_transient('eipsi_recovery_992207_992221'),'Failed recovery advanced state');};
$tests['Deactivation cleans notification singles without clinical data loss']=function(){
 $plugin=plugin_basename(EIPSI_FORMS_PLUGIN_FILE);$before=m5_assignment();
 foreach(array('eipsi_wave_available_retry','eipsi_scheduled_nudge_event','eipsi_process_nudge_jobs','eipsi_send_manual_reminder') as $hook){wp_schedule_single_event(time()+600,$hook,array('m5_fixture'));}
 try{deactivate_plugins($plugin);foreach(array('eipsi_wave_available_retry','eipsi_scheduled_nudge_event','eipsi_process_nudge_jobs','eipsi_send_manual_reminder') as $hook){m0_assert(!wp_next_scheduled($hook,array('m5_fixture')),'Notification cron remains');}m0_assert(m5_assignment()->status===$before->status&&m5_assignment()->due_at===$before->due_at,'Clinical state altered');}
 finally{$r=activate_plugin($plugin);m0_assert(!is_wp_error($r),'Reactivation failed');}
};
$tests['Repeated activation retains exact notification cron']=function(){$before=_get_cron_array();eipsi_forms_activate();eipsi_forms_activate();m0_assert(_get_cron_array()===$before,'Activation duplicated cron');};
$tests['Notification bootstrap defines owners without hook mutation']=function(){global $wp_filter;$before=array();foreach($wp_filter as $hook=>$callbacks){$before[$hook]=$callbacks->callbacks;}include EIPSI_FORMS_PLUGIN_DIR.'includes/notifications/bootstrap.php';$after=array();foreach($wp_filter as $hook=>$callbacks){$after[$hook]=$callbacks->callbacks;}m0_assert($before===$after&&class_exists('EIPSI_Notification_Nudge_Policy_Service')&&class_exists('EIPSI_Notification_Email_Delivery_Service'),'Bootstrap introduced callbacks');};
$tests['HTTP admin email configuration remains reachable']=function(){$r=m0_http('/wp-admin/',null,true);m0_assert(!is_wp_error($r)&&wp_remote_retrieve_response_code($r)===200,'Admin smoke failed');};
$tests['Longitudinal submit state precedes post commit nudge delivery']=function(){
 global $wpdb;m5_set(array('reminder_count'=>0,'due_at'=>null));$wpdb->update($wpdb->prefix.'survey_assignments',array('status'=>'pending','reminder_count'=>0),array('id'=>992232));$wpdb->update($wpdb->prefix.'survey_waves',array('offset_minutes'=>0,'window_minutes'=>60,'interval_days'=>0,'time_unit'=>'0'),array('id'=>992222));
 $states=array();$cb=function($pre)use(&$states){$states[]=m5_assignment()->status;return $pre;};add_filter('pre_wp_mail',$cb,PHP_INT_MAX);
 try{$r=EIPSI_Longitudinal_Submission_Service::handle_submission(array('wave_id'=>992221,'study_id'=>992203,'longitudinal_participant_id'=>992207,'stable_form_id'=>'m2-long-form','submitted_at'=>current_time('mysql'),'user_data'=>array('email'=>'m2-a@example.invalid')));m0_assert(!empty($r['has_next_wave'])&&!empty($states)&&count(array_filter($states,function($s){return $s!=='submitted';}))===0,'Delivery ordering: '.wp_json_encode(array($r,$states)));}
 finally{remove_filter('pre_wp_mail',$cb,PHP_INT_MAX);}
};
function m5_tokens($source){$out='';foreach(token_get_all('<?php '.$source) as $t){if(is_array($t)){if(in_array($t[0],array(T_OPEN_TAG,T_WHITESPACE,T_COMMENT,T_DOC_COMMENT),true)){continue;}$out.=$t[1];}else{$out.=$t;}}return $out;}
foreach($contracts['critical_bodies'] as $row){$tests['Frozen critical body '.$row['class'].'::'.$row['method']]=function()use($row){$r=new ReflectionMethod($row['class'],$row['method']);$source=implode('',array_slice(file($r->getFileName()),$r->getStartLine()-1,$r->getEndLine()-$r->getStartLine()+1));$s2delta=json_decode(file_get_contents(__DIR__.'/../s2/method-migrations.json'),true)[$row['class'].'::'.$row['method']]??null;if($s2delta){m0_assert(hash('sha256',m5_tokens($row['source']))===$s2delta['before_s2_tokens_sha256'],'Original M5 contract was replaced');m0_assert(hash('sha256',m5_tokens($source))===$s2delta['s2_tokens_sha256'],'Change exceeds explicit S2 delta');return;}$delta=json_decode(file_get_contents(__DIR__.'/../s1/method-migrations.json'),true)[$row['class'].'::'.$row['method']]??null;if($delta){m0_assert(hash('sha256',m5_tokens($row['source']))===$delta['before_s1_tokens_sha256'],'Original M5 contract was replaced');m0_assert(hash('sha256',m5_tokens($source))===$delta['s1_tokens_sha256'],'Change exceeds explicit S1 delta');}else m0_assert(m5_tokens($source)===m5_tokens($row['source']),'Critical rule or claim changed: '.substr(m5_tokens($source),0,150).' EXPECTED '.substr(m5_tokens($row['source']),0,150));};}
$tests['Conditioned purge removes private duplicates and retains public facades']=function(){
 $manifest=json_decode(file_get_contents(__DIR__.'/purge-manifest.json'),true);
 $classes=array('admin/services/class-email-service.php'=>'EIPSI_Email_Service','admin/services/class-wave-availability-email-service.php'=>'EIPSI_Wave_Availability_Email_Service','includes/services/class-nudge-event-scheduler.php'=>'EIPSI_Nudge_Event_Scheduler','includes/services/class-nudge-job-queue.php'=>'EIPSI_Nudge_Job_Queue','includes/services/class-nudge-cache.php'=>'EIPSI_Nudge_Cache');
 foreach($manifest['removed'] as $row){m0_assert($row['classification']==='A'&&!method_exists($classes[$row['file']],$row['method']),'Private duplicate retained');}
 m0_assert(method_exists('EIPSI_Email_Service','send_email')&&has_action('eipsi_wave_available',array('EIPSI_Nudge_Event_Scheduler','schedule_nudge_sequence'))!==false,'Public facade removed');
};
